encoder.pattern:
%d{HH:mm:ss.SSS} [%thread] %-5level %logger
                message = %msg
                sent = %X{sent}
                received = %X{received}
                total_time = %X{totalTime_ms} ms
                avg_rtt = %X{avgRtt_ms} ms
                throughput = %X{throughput_msgPerSec} msg/s
                sequence_ok = %X{sequenceOk}
                content_ok = %X{contentOk}
                server_time_ok = %X{serverTimeOk}%n%n
